package com.village.config;
import com.village.model.VillageUser; import com.village.repository.UserRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.Customizer; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.web.cors.*; import java.util.List;
@Configuration @EnableMethodSecurity public class SecurityConfig{
 @Bean SecurityFilterChain filterChain(HttpSecurity http)throws Exception{http.csrf(c->c.disable()).cors(Customizer.withDefaults()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.OPTIONS,"/**").permitAll().requestMatchers("/api/auth/register","/error").permitAll().anyRequest().authenticated()).httpBasic(b->b.authenticationEntryPoint((req,res,ex)->res.setStatus(401)));return http.build();}
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean UserDetailsService users(UserRepository repo){return username->{var u=repo.findByUsername(username).orElseThrow(()->new UsernameNotFoundException("User not found"));if(!"ACTIVE".equals(u.getStatus()))throw new UsernameNotFoundException("Account is not active");return User.withUsername(u.getUsername()).password(u.getPassword()).roles(u.getRole()).build();};}
 @Bean CommandLineRunner seedAdmin(UserRepository repo,PasswordEncoder encoder,@Value("${village.admin.username:admin}")String username,@Value("${village.admin.password:admin123}")String password){return args->{if(!repo.existsByUsername(username)){VillageUser u=new VillageUser();u.setName("Village Administrator");u.setEmail("admin@village.local");u.setPhone("");u.setUsername(username);u.setPassword(encoder.encode(password));u.setRole("ADMIN");u.setStatus("ACTIVE");u.setFamilyId("ADMIN-0001");repo.save(u);}};}
 @Bean CorsConfigurationSource corsConfigurationSource(){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(List.of("http://localhost:5173"));c.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("*"));UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}
}
